namespace UniversalPOS.Domain.Entities;
public class UserRole { public int UserId {get; private set;} public User? User {get; private set;} public int RoleId {get; private set;} public Role? Role {get; private set;} public DateTime AssignedAtUtc {get; private set;}=DateTime.UtcNow; public int? AssignedByUserId {get; private set;} private UserRole(){} public UserRole(int userId,int roleId,int? assignedByUserId=null){if(userId<=0||roleId<=0)throw new ArgumentOutOfRangeException("User and role IDs must be positive.");UserId=userId;RoleId=roleId;AssignedByUserId=assignedByUserId;} }
